"use strict";(self.webpackChunksparrow_ui_wiki=self.webpackChunksparrow_ui_wiki||[]).push([["764"],{46(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/sparrow-ui-wiki/","label":"\u{1F4D7} Introduction","docId":"intro","unlisted":false},{"type":"category","label":"\u{1F680} Getting Started","collapsed":false,"items":[{"type":"link","href":"/sparrow-ui-wiki/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/getting-started/quick-start","label":"Quick start","docId":"getting-started/quick-start","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/getting-started/concepts","label":"Core concepts and layers","docId":"getting-started/concepts","unlisted":false}],"collapsible":true},{"type":"category","label":"\u{1F4E6} Item","items":[{"type":"link","href":"/sparrow-ui-wiki/item/create","label":"Creating items","docId":"item/create","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/item/render","label":"Rendering and refresh","docId":"item/render","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/item/click","label":"Clicks and guards","docId":"item/click","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F9E9} Pane","items":[{"type":"link","href":"/sparrow-ui-wiki/pane/structure","label":"Character layouts","docId":"pane/structure","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/ingredients","label":"Filling content","docId":"pane/ingredients","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/composition","label":"Backgrounds, freezing, and nesting","docId":"pane/composition","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pane/programmatic","label":"Programmatic layouts","docId":"pane/programmatic","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F5BC} Window","items":[{"type":"link","href":"/sparrow-ui-wiki/window/lifecycle","label":"Opening and closing","docId":"window/lifecycle","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/layout","label":"Window layouts","docId":"window/layout","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/types","label":"Window types","docId":"window/types","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/title","label":"Window titles","docId":"window/title","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/window/data","label":"Window data","docId":"window/data","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F9ED} Sessions","items":[{"type":"link","href":"/sparrow-ui-wiki/session/navigation","label":"Submenus and going back","docId":"session/navigation","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/session/structures","label":"The three session structures","docId":"session/structures","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F4C4} Page & Scroll","items":[{"type":"link","href":"/sparrow-ui-wiki/pagination/page","label":"Pagination Page","docId":"pagination/page","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pagination/scroll","label":"Scroll","docId":"pagination/scroll","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/pagination/tab","label":"Tab","docId":"pagination/tab","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F392} Inventories","items":[{"type":"link","href":"/sparrow-ui-wiki/inventory/basics","label":"Putting an inventory in a menu","docId":"inventory/basics","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/virtual","label":"Virtual inventories","docId":"inventory/virtual","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/referencing","label":"Referenced inventories","docId":"inventory/referencing","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/inventory/rules-events","label":"Access rules and events","docId":"inventory/rules-events","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u2728 Visuals & Animation","items":[{"type":"link","href":"/sparrow-ui-wiki/visual/layers","label":"Visual layers","docId":"visual/layers","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/visual/animation","label":"Animations","docId":"visual/animation","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u26A1 Signal (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/why","label":"Why Signals","docId":"signal/why","unlisted":false},{"type":"category","label":"Getting started","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/basics/mutable","label":"Mutable state Signal.of","docId":"signal/basics/mutable","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/basics/subscribe","label":"Subscribing onDirty","docId":"signal/basics/subscribe","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Derivation","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/derive/map","label":"map","docId":"signal/derive/map","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive/map-distinct","label":"mapDistinct","docId":"signal/derive/map-distinct","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive/combine","label":"combine","docId":"signal/derive/combine","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive/lens","label":"lens","docId":"signal/derive/lens","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive/switching","label":"switching","docId":"signal/derive/switching","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/derive/merging","label":"merging","docId":"signal/derive/merging","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Timing","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/time/debounce","label":"debounce","docId":"signal/time/debounce","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/time/throttle","label":"throttle","docId":"signal/time/throttle","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/time/clock","label":"Clocks","docId":"signal/time/clock","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Data sources","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/source/async","label":"async","docId":"signal/source/async","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/source/polling","label":"polling","docId":"signal/source/polling","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Collections","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/collection/list","label":"ListSignal","docId":"signal/collection/list","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/collection/set","label":"SetSignal","docId":"signal/collection/set","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/collection/map","label":"MapSignal","docId":"signal/collection/map","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/collection/read-only","label":"Read-only views and online players","docId":"signal/collection/read-only","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Partitions","items":[{"type":"link","href":"/sparrow-ui-wiki/signal/keyed/basics","label":"KeyedSignal","docId":"signal/keyed/basics","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/keyed/async","label":"Async and polling partitions","docId":"signal/keyed/async","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal/keyed/player","label":"Player partitions","docId":"signal/keyed/player","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Binding Signals to Menus","items":[{"type":"link","href":"/sparrow-ui-wiki/signal-ui/item","label":"Item display","docId":"signal-ui/item","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/player","label":"Per-player display","docId":"signal-ui/player","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/list","label":"List contents","docId":"signal-ui/list","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/page","label":"Pagination and filtering","docId":"signal-ui/page","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/scroll","label":"Scrolling contents","docId":"signal-ui/scroll","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/tab","label":"Tab selection state","docId":"signal-ui/tab","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/title","label":"Window titles","docId":"signal-ui/title","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/signal-ui/visual","label":"Visual layers","docId":"signal-ui/visual","unlisted":false}],"collapsed":true,"collapsible":true}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F310} Network (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/network/listen","label":"Listening to packets","docId":"network/listen","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/network/send-receive","label":"Sending and injecting","docId":"network/send-receive","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"\u{1F4CE} Additional Notes (Optional)","items":[{"type":"link","href":"/sparrow-ui-wiki/advanced/lifecycle","label":"Object lifecycle and subscriptions","docId":"advanced/lifecycle","unlisted":false},{"type":"link","href":"/sparrow-ui-wiki/advanced/transaction","label":"Transactions and concurrency","docId":"advanced/transaction","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/sparrow-ui-wiki/faq","label":"\u2753 FAQ","docId":"faq","unlisted":false}]},"docs":{"advanced/lifecycle":{"id":"advanced/lifecycle","title":"Object lifecycle and subscriptions","description":"After a menu closes, the Window stops displaying, but the Panes, Items, and inventories it references may still serve other menus. What should be kept depends on whether the business still holds it; whether a subscription needs manual shutdown depends on the registration entry.","sidebar":"tutorialSidebar"},"advanced/transaction":{"id":"advanced/transaction","title":"Transactions and concurrency","description":"A player shift-transfers an item from the shared storage into their inventory: the storage must lose it and the inventory must gain it. The library puts the changes across the involved inventories into one transaction, written together on a successful commit; a cancellation or conflict writes none of it.","sidebar":"tutorialSidebar"},"faq":{"id":"faq","title":"\u2753 FAQ","description":"{/ Placeholder. English version is not written yet \u2014 Chinese first, see WIKI-PLAN.md section 13.1. /}","sidebar":"tutorialSidebar"},"getting-started/concepts":{"id":"getting-started/concepts","title":"Core concepts and layers","description":"A Window manages the window, a Pane arranges the layout, and an Element describes what goes in each slot. Panes can nest, and one Window can take several Panes at once.","sidebar":"tutorialSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Compatibility","sidebar":"tutorialSidebar"},"getting-started/quick-start":{"id":"getting-started/quick-start","title":"Quick start","description":"A simple welcome menu","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"\u{1F4D7} Introduction","description":"Welcome to the Sparrow UI docs! \u{1F426}","sidebar":"tutorialSidebar"},"inventory/basics":{"id":"inventory/basics","title":"Putting an inventory in a menu","description":"Pane slots can link to an inventory; whatever players put in or take out lives in that inventory. Put, take, drag, shift transfer, double-click collection, and number-key swaps all follow vanilla chest rules, with no click logic to write yourself.","sidebar":"tutorialSidebar"},"inventory/referencing":{"id":"inventory/referencing","title":"Referenced inventories","description":"A ReferencingInventory maps an existing container, such as a chest or a player inventory, into the menu. It stores nothing itself: reads return the mapped container\'s current contents, and writes go straight into the mapped container.","sidebar":"tutorialSidebar"},"inventory/rules-events":{"id":"inventory/rules-events","title":"Access rules and events","description":"Access rules decide whether a player may put items into or take items out of an inventory. Events notify you around every content change: before commit you can cancel or rewrite the change, and after commit you can log it or send a message.","sidebar":"tutorialSidebar"},"inventory/virtual":{"id":"inventory/virtual","title":"Virtual inventories","description":"A VirtualInventory keeps items in memory, fitting slots the menu manages itself: input slots, storages, reward chests. It can cap per-slot stacks, reorder bulk operations, and serialize its contents to a byte array and back.","sidebar":"tutorialSidebar"},"item/click":{"id":"item/click","title":"Clicks and guards","description":"An Item\'s interaction consists of conditional guards and handlers. Guards decide whether the interaction is allowed at all; handlers run after they pass, closing the window, sending a message, and so on.","sidebar":"tutorialSidebar"},"item/create":{"id":"item/create","title":"Creating items","description":"An arrow in a menu can carry information, turn a page, or go back when clicked. Sparrow UI describes a menu item like this with an Item: it decides what to display and what happens when a player interacts with it.","sidebar":"tutorialSidebar"},"item/render":{"id":"item/render","title":"Rendering and refresh","description":"An Item\'s display source can compute its item at display time. When the viewer\'s level, the current time, or a points value in the database changes, a refresh recomputes what is shown.","sidebar":"tutorialSidebar"},"network/listen":{"id":"network/listen","title":"Listening to packets","description":"This network API was built for Sparrow UI\'s own needs and later polished for outside use. It sits near a simplified PacketEvents in feature terms, with the implementation favoring processing efficiency, but it is not treated as absolutely stable.","sidebar":"tutorialSidebar"},"network/send-receive":{"id":"network/send-receive","title":"Sending and injecting","description":"The network API grew out of Sparrow UI\'s own needs and was polished for outside use. It approaches a simplified PacketEvents in capability, with the implementation favoring processing efficiency, but stability is not promised. Prefer the UI APIs for ordinary menu features.","sidebar":"tutorialSidebar"},"pagination/page":{"id":"pagination/page","title":"Pagination Page","description":"When a catalog has more entries than one page can hold, Page splits it across pages. Give it a list and a page size, and buttons can flip to the previous or next page.","sidebar":"tutorialSidebar"},"pagination/scroll":{"id":"pagination/scroll","title":"Scroll","description":"When menu content should be read one row downward or one column rightward at a time, use Scroll. Showing two rows at once, one downward scroll moves the former second row to the top and brings in a fresh row below.","sidebar":"tutorialSidebar"},"pagination/tab":{"id":"pagination/tab","title":"Tab","description":"When a menu has categories like \\"Materials\\" and \\"Tools\\", Tab switches the content of one area in place. Each category maps to a child Pane, each with its own layout and buttons.","sidebar":"tutorialSidebar"},"pane/composition":{"id":"pane/composition","title":"Backgrounds, freezing, and nesting","description":"A Pane\'s background fills the slots that hold no content, and freezing stops a Pane from reacting to player interaction for a while. A Pane can also be nested inside another Pane, or shown in several players\' Windows at once.","sidebar":"tutorialSidebar"},"pane/ingredients":{"id":"pane/ingredients","title":"Filling content","description":"addIngredient binds content to the identifiers in the template. Beyond Items, it can bind inventories, other Panes, or generate content slot by slot.","sidebar":"tutorialSidebar"},"pane/programmatic":{"id":"pane/programmatic","title":"Programmatic layouts","description":"Slots on a Pane can also be filled directly by slot index or coordinate, without a character template, or you can pick an ordered set of slots first and fill them one by one. Once the menu is open, all of these methods remain callable.","sidebar":"tutorialSidebar"},"pane/structure":{"id":"pane/structure","title":"Character layouts","description":"A Pane\'s layout is described with a character template: each string is one row of the menu, each character takes one slot, and slots holding the same character display the same content.","sidebar":"tutorialSidebar"},"session/navigation":{"id":"session/navigation","title":"Submenus and going back","description":"The previous chapters covered building and opening a single Window. A menu with product details, category lists, and other submenus needs to manage moving between and back across several Windows. A WindowSession represents one player\'s session from opening the menu to leaving it: it records how the Windows relate and runs a callback when the whole session ends.","sidebar":"tutorialSidebar"},"session/structures":{"id":"session/structures","title":"The three session structures","description":"Sparrow UI offers three session structures: stack, retained stack, and tree. They differ in which Window a return goes to, and whether the Window you left is kept afterwards.","sidebar":"tutorialSidebar"},"signal-ui/item":{"id":"signal-ui/item","title":"Item display","description":"The attribute menu has a \\"Strength\\" button whose name shows the current level and the remaining skill points. Each click raises Strength by one and spends a point, and the name follows; once the points run out, clicking does nothing.","sidebar":"tutorialSidebar"},"signal-ui/list":{"id":"signal-ui/list","title":"List contents","description":"The first row of the party menu shows a head for each member. When someone joins, another head appears at the end; when someone leaves, the others move up and the last slot empties.","sidebar":"tutorialSidebar"},"signal-ui/page":{"id":"signal-ui/page","title":"Pagination and filtering","description":"The quest log has twelve quests, nine per page. On the first page \\"Previous\\" should be gray, on the last page \\"Next\\" should be gray, and a page number like \\"1 / 2\\" sits in the middle.","sidebar":"tutorialSidebar"},"signal-ui/player":{"id":"signal-ui/player","title":"Per-player display","description":"The minigame lobby has a \\"Ready\\" button. After Alice clicks it, her button says \\"Ready\\", while Bob\'s still says \\"Click to ready\\".","sidebar":"tutorialSidebar"},"signal-ui/scroll":{"id":"signal-ui/scroll","title":"Scrolling contents","description":"The achievements menu shows unlocked achievements in three columns, two rows at a time. When the player scrolls down, the button should show which row they are on; at the bottom, it should stop responding.","sidebar":"tutorialSidebar"},"signal-ui/tab":{"id":"signal-ui/tab","title":"Tab selection state","description":"The skill menu has a class tab on each side, Warrior and Mage, with the current class\'s skill in the middle. When the player switches to Mage, the middle should show the Mage skill and the Mage tab should get a \\"\u25B6\\" in front of it.","sidebar":"tutorialSidebar"},"signal-ui/title":{"id":"signal-ui/title","title":"Window titles","description":"The dungeon lobby\'s window title reads \\"Dungeon lobby \xb7 1 / 4 ready\\". Each time a party member clicks ready, the number in the title should go up.","sidebar":"tutorialSidebar"},"signal-ui/visual":{"id":"signal-ui/visual","title":"Visual layers","description":"The fifth slot of the treasure hunt menu is plain floor. When the player turns on \\"Treasure detector\\" in the bottom right, that slot should show an emerald saying the treasure is here; turning it off brings the floor back. Whatever it looks like, clicking it should still run the floor\'s own handler.","sidebar":"tutorialSidebar"},"signal/basics/mutable":{"id":"signal/basics/mutable","title":"Mutable state: Signal.of","description":"The arena menu has a score item. Every kill adds a point, and the number in the menu has to follow.","sidebar":"tutorialSidebar"},"signal/basics/subscribe":{"id":"signal/basics/subscribe","title":"Subscribing: onDirty","description":"Once the boss fight starts, the BossBar at the top of the screen has to follow the boss\'s health. Health changes in the damage event; the BossBar lives somewhere else. The two need a way to talk.","sidebar":"tutorialSidebar"},"signal/collection/list":{"id":"signal/collection/list","title":"ListSignal","description":"In a minigame room\'s waiting menu, each slot shows one queued player and a corner item says \\"Waiting 3 / 8\\". Players join and leave at any time.","sidebar":"tutorialSidebar"},"signal/collection/map":{"id":"signal/collection/map","title":"MapSignal","description":"During a team fight, kills are recorded per player name, and the scoreboard menu shows who is leading at the top.","sidebar":"tutorialSidebar"},"signal/collection/read-only":{"id":"signal/collection/read-only","title":"Read-only views and online players","description":"A room\'s waiting queue should only be changed by the room itself; menus, scoreboards, and other modules just display it. Hand out the MutableListSignal, though, and anyone can call clear() and wipe the queue.","sidebar":"tutorialSidebar"},"signal/collection/set":{"id":"signal/collection/set","title":"SetSignal","description":"In the waypoint menu, places the player has visited show as maps and the rest show as question marks, with discovery progress at the top. The first time a player reaches a waypoint, it is recorded.","sidebar":"tutorialSidebar"},"signal/derive/combine":{"id":"signal/derive/combine","title":"combine","description":"The Fireball button on the skill bar is lit when it can be cast and gray when it cannot. That depends on three things: whether there is enough mana, how much mana it costs, and whether the player is silenced.","sidebar":"tutorialSidebar"},"signal/derive/lens":{"id":"signal/derive/lens","title":"lens","description":"A player\'s HUD settings live in a record with two fields, \\"show coordinates\\" and \\"interface scale\\". The settings menu has one button that toggles coordinates and another that adjusts the scale.","sidebar":"tutorialSidebar"},"signal/derive/map":{"id":"signal/derive/map","title":"map","description":"A player\'s health lives in a Signal, but the menu needs to show text like \\"\u2764 14 / 20\\", plus a ten-segment health bar.","sidebar":"tutorialSidebar"},"signal/derive/map-distinct":{"id":"signal/derive/map-distinct","title":"mapDistinct","description":"The status menu has an icon that shows \\"Healthy\\", \\"Wounded\\", or \\"Dying\\" depending on health. In a fight, health drops almost every second, but the icon only changes once in a while.","sidebar":"tutorialSidebar"},"signal/derive/merging":{"id":"signal/derive/merging","title":"merging","description":"The party menu shows the party\'s total health. Each member\'s health is its own Signal, and members join and leave at any time.","sidebar":"tutorialSidebar"},"signal/derive/switching":{"id":"signal/derive/switching","title":"switching","description":"The skill menu has two class tabs at the top, Warrior and Mage, and shows the remaining skill points of the current class below. Each class\'s skill points live in their own Signal.","sidebar":"tutorialSidebar"},"signal/keyed/async":{"id":"signal/keyed/async","title":"Async and polling partitions","description":"The guild menu shows each guild\'s name and level, stored in a database. The server has hundreds of guilds, and a player looks at one or two at a time.","sidebar":"tutorialSidebar"},"signal/keyed/basics":{"id":"signal/keyed/basics","title":"KeyedSignal","description":"The arena list menu has an icon for each of the desert, forest, and tundra arenas, showing its current player count. When someone enters or leaves an arena, only that icon should change.","sidebar":"tutorialSidebar"},"signal/keyed/player":{"id":"signal/keyed/player","title":"Player partitions","description":"Skill points are shared by the skill tree menu, the attribute menu, and the level-up prompt, one set per player. When Alice levels up and gains points, Bob\'s menus should not refresh.","sidebar":"tutorialSidebar"},"signal/source/async":{"id":"signal/source/async","title":"async","description":"A player opens their profile menu and expects to see their kills and deaths. The stats live in a database.","sidebar":"tutorialSidebar"},"signal/source/polling":{"id":"signal/source/polling","title":"polling","description":"In the lobby\'s minigame menu, the Bed Wars icon says \\"128 playing\\". The count lives in Redis and is updated by each game server.","sidebar":"tutorialSidebar"},"signal/time/clock":{"id":"signal/time/clock","title":"Clocks","description":"Once a minigame room is full, the menu shows \\"Starting in 10 seconds\\" and counts down every second. Skill cooldowns are the same: the remaining time has to refresh every second.","sidebar":"tutorialSidebar"},"signal/time/debounce":{"id":"signal/time/debounce","title":"debounce","description":"In an item search menu, the player types into an anvil input box and matching items are listed below. Every keystroke changes the Signal.","sidebar":"tutorialSidebar"},"signal/time/throttle":{"id":"signal/time/throttle","title":"throttle","description":"While a schematic is pasted, the placed block count goes up with every block. The progress menu shows \\"Placed 800 / 5000\\", but the count changes thousands of times per second.","sidebar":"tutorialSidebar"},"signal/why":{"id":"signal/why","title":"Why Signals","description":"The data a menu shows changes: a boss\'s health is dropping, a player\'s coins just arrived, a few units of a product sold. A Signal holds a changing value and notifies its dependents when it changes, so they can redraw. The menus built from fixed data in the previous chapters follow the data automatically once a Signal is attached.","sidebar":"tutorialSidebar"},"visual/animation":{"id":"visual/animation","title":"Animations","description":"An animation changes a slot\'s display frame by frame for a while, then the original look returns. Like visual layers, it changes only the display: real items stay untouched, and clicks are unaffected.","sidebar":"tutorialSidebar"},"visual/layers":{"id":"visual/layers","title":"Visual layers","description":"Visual layers decide how a slot looks, without touching the real item in it. What the player sees comes from the visual layer; clicks, shift transfers, code reads, and events all keep using the real item.","sidebar":"tutorialSidebar"},"window/data":{"id":"window/data","title":"Window data","description":"A Window can carry business objects for click handlers to read. This page also covers client state confirmation and the cursor data and cancellation in outside-click events.","sidebar":"tutorialSidebar"},"window/layout":{"id":"window/layout","title":"Window layouts","description":"The top of a Window is the container; the bottom is the player inventory. The bottom is fixed: three rows of main storage plus one hotbar row, 36 slots in total. You can lay out only the top menu, or put menu content in the bottom as well.","sidebar":"tutorialSidebar"},"window/lifecycle":{"id":"window/lifecycle","title":"Opening and closing","description":"A Window presents a Pane to one player and owns opening, closing, and player interaction in between. Each menu open usually creates a fresh Window; the Pane can be shared as needed.","sidebar":"tutorialSidebar"},"window/title":{"id":"window/title","title":"Window titles","description":"A Window\'s title can be fixed text or generated from business data. After the menu opens, the title can still be updated through the Window.","sidebar":"tutorialSidebar"},"window/types":{"id":"window/types","title":"Window types","description":"Sparrow UI covers 17 vanilla container windows. A regular chest suits free-form layouts; when you need text input, a progress bar, or a trade list, pick a window that ships with those widgets.","sidebar":"tutorialSidebar"}}}}')}}]);